changeSet.sql:
alter table cleaning_order drop constraint ck_cleaning_order_status;
alter table cleaning_order
    add constraint ck_cleaning_order_status check (
        status in ('NEW', 'ACCEPTED', 'AWAITING_REPORT', 'ONSITE_ISSUE_REPORTED',
                   'COMPLETED', 'REJECTED', 'CANCELLED')
    );

alter table cleaning_order_event drop constraint ck_cleaning_order_event_type;
alter table cleaning_order_event drop constraint ck_cleaning_order_event_actor;
alter table cleaning_order_event drop constraint ck_cleaning_order_event_from_status;
alter table cleaning_order_event drop constraint ck_cleaning_order_event_to_status;

alter table cleaning_order_event
    add constraint ck_cleaning_order_event_type check (
        event_type in ('IMPORTED', 'CREATED', 'ACCEPTED', 'REPORT_STARTED',
                       'PHOTO_ADDED', 'COMMENT_UPDATED', 'ONSITE_ISSUE_REPORTED',
                       'ISSUE_PHOTO_ADDED', 'ISSUE_REPORT_SUBMITTED',
                       'ISSUE_CUSTOMER_NOTIFIED', 'ISSUE_RESOLVED', 'COMPLETED',
                       'CANCELLED_BY_CUSTOMER', 'CANCELLED_BY_CLEANER')
    ),
    add constraint ck_cleaning_order_event_actor
        check (actor_type in ('CUSTOMER', 'CLEANER', 'ADMIN', 'SYSTEM')),
    add constraint ck_cleaning_order_event_from_status check (
        from_status is null or from_status in
        ('NEW', 'ACCEPTED', 'AWAITING_REPORT', 'ONSITE_ISSUE_REPORTED',
         'COMPLETED', 'REJECTED', 'CANCELLED')
    ),
    add constraint ck_cleaning_order_event_to_status check (
        to_status in ('NEW', 'ACCEPTED', 'AWAITING_REPORT', 'ONSITE_ISSUE_REPORTED',
                      'COMPLETED', 'REJECTED', 'CANCELLED')
    );

create unique index uq_issue_report_active_per_cleaner on cleaning_order_issue_report (cleaner_telegram_user_id) where input_active = true and submitted_at is null;
alter table cleaning_order_issue_report add constraint ck_issue_report_reason check ( reason in ('APARTMENT_SIZE_MISMATCH', 'CLEANING_TYPE_MISMATCH', 'HEAVY_CONTAMINATION', 'ACCESS_PROBLEM', 'ADDRESS_MISMATCH', 'OTHER') ), add constraint ck_issue_report_resolution check ( (resolved_at is null and resolved_by is null and resolution_comment is null) or (resolved_at is not null and resolved_by is not null and resolution_comment is not null) );
alter table cleaning_order_issue_photo add constraint ck_issue_photo_size check (size_bytes > 0), add constraint ck_issue_photo_content_type check (content_type in ('image/jpeg', 'image/png')), add constraint ck_issue_photo_sha256 check (sha256 ~ '^[0-9a-f]{64}$');

